select * from (select location, case when budget >= 3596000 then 'high' when budget >= 886000 then 'mid' else 'low' end budget_bucket, sum(case when dept_name = 'Marketing' then 1 else 0 end) marketing_count from departments group by location, case when budget >= 3596000 then 'high' when budget >= 886000 then 'mid' else 'low' end) agg where marketing_count < 63 order by marketing_count desc;
